function hasContract() {
  const a = AGENT_CARD_CONFIG.contractAddress;
  return typeof a === "string" && /^0x[0-9a-fA-F]{40}$/.test(a);
}
function contractAddress() { return AGENT_CARD_CONFIG.contractAddress; }
function pad4(n) { return String(n).padStart(4, "0"); }
function shortAddr(addr) { return addr ? addr.slice(0, 6) + "…" + addr.slice(-4) : ""; }
function explorerTx(hash) { return AGENT_CARD_CONFIG.explorer + "/tx/" + hash; }
function explorerAddress(addr) { return AGENT_CARD_CONFIG.explorer + "/address/" + addr; }
function explorerToken(tokenId) { return AGENT_CARD_CONFIG.explorer + "/token/" + contractAddress() + "?a=" + tokenId; }
function formatBNB(wei) {
  try {
    const s = window.ethers.formatEther(wei);
    return s.includes(".") ? s.replace(/0+$/, "").replace(/\.$/, "") : s;
  } catch (e) { return "—"; }
}
function withTimeout(promise, ms) {
  return Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error("Timed out while reading the network.")), ms))]);
}
function escapeXml(value) {
  return String(value).replace(/[<>&'"]/g, (char) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", "'": "&apos;", '"': "&quot;" }[char]));
}

function artPath(personaKey) { return "assets/art-" + personaKey + ".webp"; }

function glyphMarkup(kind) {
  if (kind === "builder") {
    return '<path d="M50 12 83 31v38L50 88 17 69V31L50 12Z" fill="none" stroke="currentColor" stroke-width="3"/><path d="m17 31 33 19 33-19M50 50v38M33 22l34 19M67 22 33 41" fill="none" stroke="currentColor" stroke-width="2"/><path d="M38 41h24v18H38z" fill="currentColor" opacity=".22"/>';
  }
  if (kind === "explorer") {
    return '<circle cx="50" cy="50" r="34" fill="none" stroke="currentColor" stroke-width="2"/><path d="m62 32-8 22-22 14 8-22 22-14Z" fill="currentColor"/><circle cx="50" cy="50" r="4" fill="#fff"/><path d="M50 8v9M50 83v9M8 50h9M83 50h9" stroke="currentColor" stroke-width="2"/>';
  }
  return '<path d="M50 12 80 24v22c0 20-12 34-30 42C32 80 20 66 20 46V24l30-12Z" fill="none" stroke="currentColor" stroke-width="3"/><path d="m36 50 9 9 20-22" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="50" cy="50" r="44" fill="none" stroke="currentColor" stroke-width="1" stroke-dasharray="2 5" opacity=".45"/>';
}

function rawName() { return $("#agentName").value.trim(); }
function aiBase() { let v = rawName().trim().toLowerCase(); if (v.endsWith(".ai")) v = v.slice(0, -3); return v; }
function rawSignature() { const el = $("#agentSignature"); return el ? el.value.trim() : ""; }
function validInput() {
  let nameValid;
  if (state.nameMode === "ai") {
    nameValid = /^[a-z0-9_-]{3,24}$/.test(aiBase());
  } else {
    const value = rawName();
    nameValid = value.length >= 1 && value.length <= 32 && /^[A-Za-z0-9 ._-]+$/.test(value);
  }
  const nameErrorEl = $("#nameError");
  if (nameErrorEl) nameErrorEl.textContent = state.nameMode === "ai"
    ? "Enter your Agent ID: 3\u201324 characters of lowercase letters, numbers, dashes, or underscores (without .ai \u2014 it is added automatically)."
    : "Enter 1\u201332 characters: letters, numbers, spaces, dots, underscores, or dashes only.";
  const sig = rawSignature();
  const sigValid = sig.length <= 24 && /^[A-Za-z0-9 ._-]*$/.test(sig);
  $("#nameError").hidden = nameValid;
  $("#agentName").setAttribute("aria-invalid", String(!nameValid));
  const signError = $("#signError");
  if (signError) signError.hidden = sigValid;
  return nameValid && sigValid;
}
function getName() { if (state.nameMode === "ai") return (aiBase() || "agent") + ".ai"; return rawName() || "agent-name"; }

function activePrice() { return state.tier === 1 ? chainState.paidPrice : chainState.freePrice; }
function editionName(tier) { const t = tier == null ? state.tier : tier; return t === 1 ? "PAID EDITION ★" : "FREE EDITION"; }
function syncTierUI() {
  $$(".tier-option").forEach((option) => {
    const selected = Number(option.dataset.tier) === state.tier;
    option.classList.toggle("is-selected", selected);
    option.setAttribute("aria-pressed", String(selected));
  });
  const note = $("#tierNote");
  if (note) {
    if (chainState.freePrice != null && chainState.paidPrice != null) {
      note.textContent = "Live from the contract — Free: " + formatBNB(chainState.freePrice) + " BNB (free 1x per wallet)" + (state.freeUsed ? " · this wallet's free mint is already used" : "") + " · Paid: " + formatBNB(chainState.paidPrice) + " BNB · max 2 mints per wallet in total.";
    } else if (hasContract()) {
      note.textContent = "Prices are read live from the contract once the data loads.";
    } else {
      note.textContent = "Free 1x per wallet · max 2 cards per wallet in total. Live prices appear once the contract is deployed.";
    }
  }
}

function nextTokenLabel() {
  return null; // the serial number is drawn randomly on-chain from the #1-#4444 pool at mint
}

function updateEditionLabels() {
  const label = nextTokenLabel();
  const previewEdition = $("#previewEdition");
  const previewSerial = $("#previewSerial");
  if (previewEdition) previewEdition.textContent = "ONE AND ONLY";
  if (previewSerial) previewSerial.textContent = label ? label + " · " + editionName() : editionName() + " · RANDOM NUMBER";
  const heroEdition = $("#heroEdition");
  const heroSerial = $("#heroSerial");
  if (heroEdition) heroEdition.textContent = "ONE AND ONLY";
  if (heroSerial) heroSerial.textContent = label ? label + " · PAID EDITION ★" : "PAID EDITION ★ · RANDOM NUMBER";
  const caption = $("#previewSupplyCaption");
  if (caption) {
    caption.textContent = chainState.totalMinted != null
      ? chainState.totalMinted.toLocaleString("en-US") + " / " + (chainState.maxSupply || 4444).toLocaleString("en-US") + " MINTED"
      : "4,444-CARD COLLECTION";
  }
}

function applyEditionToClone(clone, label) {
  const edition = clone.querySelector(".card-edition");
  const serial = clone.querySelector(".card-serial");
  if (edition) edition.textContent = "ONE AND ONLY";
  if (serial) serial.textContent = label ? label + " · " + editionName() : editionName() + " · RANDOM NUMBER";
}

const tcgData = {
  guardian: { power: 120, ability: "Market Gravity", abilityText: "Its size alone bends the order book.", moves: [["Deep Bid", "60"], ["Tsunami Buy", "90"]] },
  builder: { power: 110, ability: "Blood Scent", abilityText: "Smells a weak position from miles away.", moves: [["Apex Bite", "55"], ["Feeding Frenzy", "95"]] },
  explorer: { power: 100, ability: "One-Shot Entry", abilityText: "Waits hours for a single perfect entry.", moves: [["Silent Limit", "50"], ["Headshot Fill", "100"]] },
};

function fillTcg(cardEl, personaKey, tier) {
  if (!cardEl) return;
  const data = tcgData[personaKey];
  if (!data) return;
  const power = cardEl.querySelector(".tcg-power b");
  if (power) power.textContent = String(data.power + (tier === 1 ? 30 : 0));
  const abilityName = cardEl.querySelector(".tcg-ability-name");
  if (abilityName) abilityName.textContent = data.ability;
  const abilityText = cardEl.querySelector(".tcg-ability-text");
  if (abilityText) abilityText.textContent = data.abilityText;
  cardEl.querySelectorAll(".tcg-move").forEach((row, i) => {
    const move = data.moves[i];
    if (!move) return;
    const nameEl = row.querySelector(".tcg-move-name");
    const dmgEl = row.querySelector(".tcg-move-dmg");
    if (nameEl) nameEl.textContent = move[0];
    if (dmgEl) dmgEl.textContent = move[1];
  });
}

function updateCard() {
  state.name = getName();
  state.signature = rawSignature();
  const signEl = $("#previewSign");
  const useDrawn = state.signMode === "draw" && Boolean(state.signDrawn);
  if (signEl) signEl.textContent = useDrawn ? "" : state.signature;
  const signImg = $("#previewSignImg");
  if (signImg) { signImg.hidden = !useDrawn; if (useDrawn) signImg.src = state.signDrawn; }
  const monoEl = $("#previewMono");
  if (monoEl) monoEl.textContent = (state.name || "").charAt(0);
  const card = $("#cardPreview");
  card.className = "collectible-card theme-" + state.color + (state.tier === 1 ? " card-paid" : " card-free");
  const chip = card.querySelector(".card-chip");
  if (chip) chip.textContent = state.tier === 1 ? "PREMIUM" : "STANDARD";
  $("#previewName").textContent = state.name;
  $("#previewName").style.fontSize = (state.name.length <= 10 ? 34 : state.name.length <= 14 ? 30 : state.name.length <= 20 ? 25 : state.name.length <= 26 ? 21 : 18) + "px";
  $("#previewRole").textContent = personaConfig[state.persona].title.toUpperCase();
  $("#colorName").textContent = colorConfig[state.color].label;
  const previewArt = $("#previewGlyph"); if (previewArt) previewArt.src = artPath(state.persona);
  card.setAttribute("aria-label", "Card preview: " + state.name + ", " + personaConfig[state.persona].title);
  fillTcg(card, state.persona, state.tier);
  updateEditionLabels();
  updateCardSlots();
  updateXShare();
}

function updateCardSlots() {
  const original = $("#cardPreview");
  const nextLabel = nextTokenLabel();
  const mintedLabel = mintedResult ? "No. " + pad4(mintedResult.tokenId) : null;
  [["confirmCardSlot", nextLabel], ["successCardSlot", mintedLabel || nextLabel]].forEach(([id, label]) => {
    const slot = document.getElementById(id);
    if (!slot) return;
    const clone = original.cloneNode(true);
    clone.removeAttribute("id");
    clone.setAttribute("aria-hidden", "true");
    const art = clone.querySelector(".card-art-img");
    if (art) art.src = artPath(state.persona);
    const nameEl = clone.querySelector("strong");
    const roleEl = clone.querySelector(".card-role");
    if (nameEl) nameEl.textContent = state.name;
    if (roleEl) roleEl.textContent = personaConfig[state.persona].title.toUpperCase();
    const classEl = clone.querySelector(".card-class");
    if (classEl) classEl.textContent = mintedResult ? serialClassLabel(mintedResult.tokenId) : "";
    const cSignImg = clone.querySelector(".card-sign-img");
    if (cSignImg) { const ud = state.signMode === "draw" && Boolean(state.signDrawn); cSignImg.hidden = !ud; if (ud) cSignImg.src = state.signDrawn; }
    const cSign = clone.querySelector(".card-sign");
    if (cSign && state.signMode === "draw" && state.signDrawn) cSign.textContent = "";
    applyEditionToClone(clone, label);
    slot.replaceChildren(clone);
  });
  const confirmName = $("#confirmName");
  if (confirmName) confirmName.textContent = state.name + " · " + personaConfig[state.persona].title + " · " + editionName();
}

function syncHeroCard() {
  const card = document.getElementById("heroCard");
  if (!card) return;
  card.className = "collectible-card theme-" + heroState.color + " card-paid";
  const role = document.getElementById("heroCardRole");
  const glyph = document.getElementById("heroGlyph");
  const colorName = document.getElementById("heroColorName");
  if (role) role.textContent = personaConfig[heroState.persona].title.toUpperCase();
  if (glyph) glyph.src = artPath(heroState.persona);
  if (colorName) colorName.textContent = colorConfig[heroState.color].label;
  card.setAttribute("aria-label", "Card nara.ai, " + personaConfig[heroState.persona].title);
  fillTcg(card, heroState.persona, 1);
  updateEditionLabels();
  $$(".hero-persona").forEach((button) => {
    const selected = button.dataset.persona === heroState.persona;
    button.classList.toggle("is-selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  $$(".hero-color-row .color-swatch").forEach((swatch) => {
    const selected = swatch.dataset.color === heroState.color;
    swatch.classList.toggle("is-selected", selected);
    swatch.setAttribute("aria-pressed", String(selected));
  });
}

function updateXShare() {
  const link = document.getElementById("xShareButton");
  if (!link) return;
  let text;
  if (mintedResult) {
    text = "I just minted Agent Card #" + pad4(mintedResult.tokenId) + " (" + state.name + ", " + personaConfig[state.persona].title + ") on BNB Chain — the card data is stored on-chain. Not an official Binance Agent ID. Mint proof: " + explorerTx(mintedResult.txHash);
  } else {
    text = "I designed an Agent ID card " + state.name + " (" + personaConfig[state.persona].title + ") at Agent Card Studio — a collectible NFT mint on BNB Chain, with the card data stored on-chain. Not an official Binance Agent ID.";
  }
  link.href = "https://x.com/intent/post?text=" + encodeURIComponent(text);
}

function launchConfetti() {
  if (prefersReducedMotion) return;
  const colors = ["#d5fa61", "#c7b5ff", "#ff8b74", "#78d9ee", "#9ab82c"];
  for (let i = 0; i < 34; i += 1) {
    const piece = document.createElement("span");
    piece.className = "confetti-piece";
    piece.setAttribute("aria-hidden", "true");
    piece.style.left = ((i * 29) % 96 + 2) + "%";
    piece.style.background = colors[i % colors.length];
    piece.style.animationDelay = ((i % 9) * 55) + "ms";
    piece.style.animationDuration = (1400 + (i % 5) * 140) + "ms";
    piece.style.transform = "rotate(" + (i * 47) + "deg)";
    document.body.append(piece);
    setTimeout(() => piece.remove(), 2600);
  }
}

function showToast(message) {
  const toast = $("#toast");
  toast.textContent = message;
  toast.classList.add("is-visible");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("is-visible"), 3200);
}

function setStep(step) {
  $$(".step-item").forEach((item) => {
    const n = Number(item.dataset.step);
    item.classList.toggle("is-active", n === step);
    item.classList.toggle("is-done", n < step);
  });
}

function showView(viewId, step) {
  views.forEach((id) => { document.getElementById(id).hidden = id !== viewId; });
  setStep(step);
  const studio = $("#studio");
  if (studio) window.scrollTo({ top: studio.offsetTop - 16, behavior: prefersReducedMotion ? "auto" : "smooth" });
}

/* ---------- Contract status & public data ---------- */

function setChainStatus(mode) {
  const pillText = $("#chainStatusText");
  const badge = $("#heroBadge");
  const studioNote = $("#studioNote");
  const contractText = $("#contractStatusText");
  const priceNote = $("#heroPriceNote");
  let pill = "BNB CHAIN · CHECKING…";
  let badgeText = "BNB CHAIN · CHECKING CONTRACT STATUS";
  let note = "Checking the contract status on BNB Chain…";
  let contractLabel = "CHECKING…";
  let price = "Checking the contract status on BNB Chain…";
  if (mode === "no-contract") {
    pill = "BNB CHAIN · KONTRAK BELUM DITERBITKAN";
    badgeText = "BNB CHAIN · KONTRAK BELUM DITERBITKAN";
    note = "The contract is not deployed yet.<br />Minting opens once the owner deploys it.";
    contractLabel = "KONTRAK BELUM DITERBITKAN";
    price = "Contract not deployed yet — you can still try the design; minting opens once the owner deploys the contract.";
  } else if (mode === "ok" || mode === "closed") {
    const total = chainState.totalMinted != null ? chainState.totalMinted.toLocaleString("en-US") : "—";
    const max = (chainState.maxSupply || 4444).toLocaleString("en-US");
    const priceBnb = "Free " + (chainState.freePrice != null ? formatBNB(chainState.freePrice) : "—") + " / Paid " + (chainState.paidPrice != null ? formatBNB(chainState.paidPrice) : "—");
    const openLabel = mode === "ok" ? "MINT OPEN" : "MINT CLOSED";
    pill = "BNB CHAIN · " + openLabel + " · " + total + "/" + max;
    badgeText = "LIVE DI BNB CHAIN · " + openLabel;
    note = openLabel.charAt(0) + openLabel.slice(1).toLowerCase() + " · " + total + " of " + max + " cards minted.<br />Price: " + priceBnb + " BNB + gas. Free max 1x per wallet.";
    contractLabel = openLabel;
    price = "Live price: " + priceBnb + " BNB + gas · " + total + "/" + max + " cards minted.";
  } else if (mode === "error") {
    pill = "BNB CHAIN · DATA KONTRAK TIDAK TERBACA";
    badgeText = "BNB CHAIN · DATA KONTRAK TIDAK TERBACA";
    note = "Contract data is unavailable right now.<br />Try reloading the page.";
    contractLabel = "DATA TIDAK TERBACA";
    price = "Contract data is unavailable right now — check your connection and reload the page.";
  } else if (mode === "no-ethers") {
    pill = "BNB CHAIN · PUSTAKA WALLET GAGAL DIMUAT";
    badgeText = "BNB CHAIN · PUSTAKA WALLET GAGAL DIMUAT";
    note = "The wallet library failed to load.<br />Check your connection and reload.";
    contractLabel = "PUSTAKA GAGAL DIMUAT";
    price = "The wallet library failed to load — check your connection and reload the page.";
  }
  if (pillText) pillText.textContent = pill;
  if (badge) badge.innerHTML = "<i aria-hidden=\"true\"></i> " + escapeXml(badgeText);
  if (studioNote) studioNote.innerHTML = note;
  if (contractText) contractText.textContent = contractLabel;
  if (priceNote) priceNote.textContent = price;
}

async function loadChainState() {
  if (chainLoading) return;
  if (!window.ethers) {
    setChainStatus("no-ethers");
    if (!ethersRetryScheduled) {
      ethersRetryScheduled = true;
      setTimeout(() => { if (window.ethers) loadChainState(); }, 2500);
    }
    return;
  }
  if (!hasContract()) {
    chainState = { totalMinted: null, freePrice: null, paidPrice: null, mintOpen: null, maxSupply: 4444, owner: null, loaded: false, error: false };
    readContract = null;
    setChainStatus("no-contract");
    updateEditionLabels();
    refreshMintUI();
    updateConfirmReceipt();
    updateOwnerPanel();
    return;
  }
  chainLoading = true;
  setChainStatus("loading");
  let lastError = null;
  for (const rpc of READ_RPCS) {
    try {
      const provider = new window.ethers.JsonRpcProvider(rpc, AGENT_CARD_CONFIG.chainId);
      const c = new window.ethers.Contract(contractAddress(), AGENT_CARD_ABI, provider);
      const [freePrice, paidPrice, total, open, max, ownerAddr] = await withTimeout(
        Promise.all([c.freeMintPrice(), c.paidMintPrice(), c.totalMinted(), c.mintOpen(), c.MAX_SUPPLY(), c.owner()]), 9000
      );
      chainState = {
        totalMinted: Number(total),
        freePrice: freePrice,
        paidPrice: paidPrice,
        mintOpen: Boolean(open),
        maxSupply: Number(max),
        owner: ownerAddr,
        loaded: true,
        error: false,
      };
      readContract = c;
      setChainStatus(chainState.mintOpen ? "ok" : "closed");
      chainLoading = false;
      updateEditionLabels();
      refreshMintUI();
      updateConfirmReceipt();
      updateOwnerPanel();
      return;
    } catch (e) { lastError = e; }
  }
  chainLoading = false;
  chainState.error = true;
  setChainStatus("error");
  refreshMintUI();
  updateConfirmReceipt();
  updateOwnerPanel();
}

function mintBlockedReason() {
  if (!hasContract()) return "The contract is not deployed yet — the owner will deploy it from their wallet.";
  if (!chainState.loaded) return "Contract data is still loading / unavailable.";
  if (!chainState.mintOpen) return "Minting is currently closed by the contract owner.";
  if (chainState.totalMinted != null && chainState.totalMinted >= chainState.maxSupply) return "The collection is sold out (" + (chainState.maxSupply || 4444).toLocaleString("en-US") + " cards).";
  if (!state.connected) return "Connect your wallet to continue.";
  if (state.chainId != null && state.chainId !== AGENT_CARD_CONFIG.chainId) return "Switch your wallet network to BNB Smart Chain (56).";
  if (state.mintCount != null && state.mintCount >= 2) return "This wallet already minted the maximum of 2 cards per wallet.";
  if (state.tier === 0 && state.freeUsed) return "This wallet already used its free mint — choose the Paid Edition to mint again.";
  return null;
}

function refreshMintUI() {
  renderMintStats();
  renderAgentPrompts();
  renderTokenPanel();
  const blocked = mintBlockedReason();
  const continueButton = $("#continueButton");
  const hint = $("#continueHint");
  const mintButton = $("#mintButton");
  if (continueButton) continueButton.disabled = !validInputSilent();
  if (hint) hint.textContent = !hasContract()
    ? "The contract is not deployed yet — the owner deploys it from their wallet, and minting opens right after."
    : "No wallet connection needed — the next step gives you a ready-to-paste prompt for your AI agent.";
  if (mintButton) {
    mintButton.disabled = Boolean(blocked) || !validInputSilent();
    const price = activePrice() != null ? formatBNB(activePrice()) : null;
    mintButton.innerHTML = (state.tier === 1 ? "Mint Paid Edition" : "Mint Free Edition") + (price ? " — " + price + " BNB" : "") + ' <span aria-hidden="true">→</span>';
  }
  syncTierUI();
  updateWalletUI();
}
function validInputSilent() {
  const value = rawName();
  return value.length >= 1 && value.length <= 32 && /^[A-Za-z0-9 ._-]+$/.test(value);
}

function updateConfirmReceipt() {
  const priceEl = $("#confirmPrice");
  const totalEl = $("#confirmTotal");
  const link = $("#confirmContractLink");
  if (link) {
    if (hasContract()) {
      link.textContent = shortAddr(contractAddress());
      link.href = explorerAddress(contractAddress());
    } else {
      link.textContent = "Not deployed yet";
      link.href = "https://agentcard.cloud/deploy.html";
    }
  }
  if (priceEl) {
    priceEl.innerHTML = activePrice() != null
      ? escapeXml(editionName()) + " · " + escapeXml(formatBNB(activePrice())) + " BNB <em>LIVE DARI KONTRAK</em>"
      : "— BNB <em>LIVE DARI KONTRAK</em>";
  }
  if (totalEl) totalEl.textContent = activePrice() != null ? formatBNB(activePrice()) + " BNB" : "— BNB";
}

function updateWalletUI() {
  const label = $("#walletButtonLabel");
  const notice = $("#walletNotice");
  const connectedBox = $("#walletConnected");
  const addrEl = $("#connectedAddress");
  const netEl = $("#connectedNetwork");
  if (state.connected && state.address) {
    if (label) label.textContent = shortAddr(state.address);
    if (notice) notice.hidden = true;
    if (connectedBox) connectedBox.hidden = false;
    if (addrEl) addrEl.textContent = state.address;
    if (netEl) netEl.textContent = state.chainId === 56 ? "BNB Smart Chain (56)" : (state.chainId ? "Jaringan lain (" + state.chainId + ") — ganti ke 56" : "BNB Smart Chain");
  } else {
    if (label) label.textContent = "Connect Wallet";
    if (notice) notice.hidden = false;
    if (connectedBox) connectedBox.hidden = true;
  }
}

/* ---------- $ACARD token, rewards, agent prompts ---------- */

function tokenAddress() { try { return localStorage.getItem("acs-token") || AGENT_CARD_CONFIG.tokenAddress || ""; } catch (e) { return AGENT_CARD_CONFIG.tokenAddress || ""; } }
function burnAddress() { try { return localStorage.getItem("acs-burn") || AGENT_CARD_CONFIG.burnAddress || ""; } catch (e) { return AGENT_CARD_CONFIG.burnAddress || ""; } }
function stakeAddress() { try { return localStorage.getItem("acs-stake") || AGENT_CARD_CONFIG.stakeAddress || ""; } catch (e) { return AGENT_CARD_CONFIG.stakeAddress || ""; } }

function agentPromptText(tier, qty) {
  const addr = hasContract() ? contractAddress() : "(contract not deployed yet - get the address at agentcard.cloud)";
  const style = personaConfig[state.persona].styleIndex;
  const nm = state.name || "myagent";
  const hex = colorConfig[state.color].hex;
  const sig = state.signature || "";
  const fp = chainState.freePrice != null ? formatBNB(chainState.freePrice) : "0.0002";
  const pp = chainState.paidPrice != null ? formatBNB(chainState.paidPrice) : "0.002";
  const call = (fn) => fn + "(\"" + nm + "\", " + style + ", \"" + hex + "\", \"" + sig + "\")";
  const head = "Mint " + qty + " Agent Card NFT(s) for me on BNB Chain. Contract: " + addr + ". Card design: name \"" + nm + "\", style " + style + " (" + personaConfig[state.persona].title + "), color \"" + hex + "\", signature \"" + sig + "\". Token IDs are drawn randomly from the shared pool #1-#4444. Max 2 cards per wallet in total. ";
  if (tier === 0 && qty === 1) return head + "First check on-chain that mintOpen() is true, my freeMintUsed is false, and my mintCount is below 2. Then call " + call("freeMint") + " with exactly " + fp + " BNB (anti-sybil fee). Do it now - no preview needed. Reply with the transaction link when done.";
  if (tier === 0) return head + "First check on-chain that mintOpen() is true, my freeMintUsed is false, and my mintCount is 0. Then (1) call " + call("freeMint") + " with exactly " + fp + " BNB (anti-sybil fee), and (2) call " + call("paidMint") + " with exactly " + pp + " BNB. Do it now - no preview needed. Reply with both transaction links when done.";
  if (qty === 1) return head + "First check on-chain that mintOpen() is true and my mintCount is below 2. Then call " + call("paidMint") + " with exactly " + pp + " BNB - the full price, nothing extra. Do it now - no preview needed. Reply with the transaction link when done.";
  return head + "First check on-chain that mintOpen() is true and my mintCount is 0 (two paid mints need both wallet slots). Then call " + call("paidMint") + " twice, each with exactly " + pp + " BNB - the full price, nothing extra. Do it now - no preview needed. Reply with both transaction links when done.";
}

function renderAgentPrompts() {
  const qtyEl = $("#agentQty");
  const qty = qtyEl ? Number(qtyEl.value || 1) : 1;
  const c = $("#agentPromptConfirm");
  if (c) c.value = agentPromptText(state.tier, qty);
  const tierLabel = $("#agentPromptTierLabel");
  if (tierLabel) tierLabel.textContent = state.tier === 1 ? "PAID EDITION" : "FREE EDITION";
  renderRewardPrompts();
}

function renderRewardPrompts() {
  const nft = hasContract() ? contractAddress() : "(NFT contract not deployed yet)";
  const b = burnAddress();
  const st = stakeAddress();
  const tk = tokenAddress();
  const bp = $("#burnPrompt");
  if (bp) bp.value = b
    ? "Burn 1 of my Agent Card NFTs for 50,000 ACARD. NFT contract: " + nft + ". Burn contract: " + b + ". Use my token #___ (fill in the token ID). Steps: (1) verify I own that token and the burn pool holds at least 50,000 ACARD; (2) approve the burn contract for my token on the NFT contract; (3) call burn(tokenId) on the burn contract with value 0.0001 BNB (the action fee). The card goes to the dead address forever and 50,000 ACARD goes to my wallet. Burning is permanent - ask me to confirm the token ID before executing. Reply with the transaction link when done."
    : "The burn contract is not deployed yet. Check agentcard.cloud for the address once it is live.";
  const sp = $("#stakePrompt");
  if (sp) sp.value = st
    ? "Stake 1 of my Agent Card NFTs to earn 500 ACARD per day. NFT contract: " + nft + ". Staking contract: " + st + ". Use my token #___ (fill in the token ID). Steps: (1) verify I own that token; (2) approve the staking contract for my token on the NFT contract; (3) call stake(tokenId) on the staking contract with value 0.0001 BNB (the action fee). Later, claim(tokenId) (free) pays my earned ACARD and unstake(tokenId) (free) pays and returns my card. Do it now - no preview needed. Reply with the transaction link when done."
    : "The staking contract is not deployed yet. Check agentcard.cloud for the address once it is live.";
  const line = $("#tokenAddressLine");
  if (line) line.textContent = tk ? ("$ACARD " + tk + " - Burn " + (b || "-") + " - Stake " + (st || "-")) : "not deployed yet";
  const pill = $("#tokenStatus");
  if (pill) pill.textContent = tk ? (b && st ? "LIVE" : "TOKEN LIVE - REWARDS PENDING") : "COMING SOON";
}

function renderMintStats() {
  const set = (id, v) => { const el = $(id); if (el) el.textContent = v; };
  const max = chainState.maxSupply || 4444;
  set("#statSupply", max.toLocaleString("en-US"));
  set("#statMinted", chainState.totalMinted != null ? chainState.totalMinted.toLocaleString("en-US") : "-");
  set("#statRemaining", chainState.totalMinted != null ? (max - chainState.totalMinted).toLocaleString("en-US") : "-");
  set("#statFreePrice", (chainState.freePrice != null ? formatBNB(chainState.freePrice) : "0.0002") + " BNB");
  set("#statPaidPrice", (chainState.paidPrice != null ? formatBNB(chainState.paidPrice) : "0.002") + " BNB");
  set("#statStatus", !hasContract() ? "NOT DEPLOYED" : chainState.mintOpen == null ? "-" : chainState.mintOpen ? "OPEN" : "CLOSED");
}

async function updateBurnedCount() {
  const el = $("#statBurned");
  if (!el) return;
  const b = burnAddress();
  if (!b || !window.ethers) { el.textContent = "-"; return; }
  try {
    const provider = new window.ethers.JsonRpcProvider(AGENT_CARD_CONFIG.rpcUrls[0]);
    const burn = new window.ethers.Contract(b, REWARD_ABI, provider);
    el.textContent = Number(await burn.totalBurned()).toLocaleString("en-US");
  } catch (e) { /* keep the last value */ }
}

function renderTokenPanel() {
  const set = (id, v) => { const el = $(id); if (el) el.textContent = v; };
  set("#tokenDeployStatus", tokenAddress() ? shortAddress(tokenAddress()) : "Not deployed");
  set("#burnDeployStatus", burnAddress() ? shortAddress(burnAddress()) : "Not deployed");
  set("#stakeDeployStatus", stakeAddress() ? shortAddress(stakeAddress()) : "Not deployed");
  set("#linkNftStatus", hasContract() ? shortAddress(contractAddress()) : "Deploy the NFT contract first");
}

async function ownerSigner() {
  if (!window.ethereum || !window.ethers) { showToast("Open this page in a wallet browser first."); return null; }
  try {
    const provider = new window.ethers.BrowserProvider(window.ethereum);
    return await provider.getSigner();
  } catch (e) { showToast("Could not get the wallet signer."); return null; }
}

async function deployWith(bytecode, abi, args) {
  const signer = await ownerSigner();
  if (!signer) return null;
  const factory = new window.ethers.ContractFactory(abi, bytecode, signer);
  const contract = await factory.deploy(...args);
  await contract.waitForDeployment();
  return contract.getAddress();
}

/* ---------- Real wallet ---------- */

function showNoWalletGuidance() {
  const text = $("#walletNoticeText");
  if (text) {
    text.innerHTML = "<strong>No wallet detected.</strong><br />Open this page in a wallet app's built-in browser (MetaMask, Trust Wallet, or Binance Wallet), or install a wallet extension in your desktop browser.";
  }
  showToast("No wallet detected in this browser.");
}

async function setupSigner() {
  signer = null;
  walletContract = null;
  if (!window.ethereum || !window.ethers) return;
  try {
    const provider = new window.ethers.BrowserProvider(window.ethereum);
    signer = await provider.getSigner();
    if (hasContract()) walletContract = new window.ethers.Contract(contractAddress(), AGENT_CARD_ABI, signer);
  } catch (e) { signer = null; walletContract = null; }
}

async function ensureChain() {
  if (!window.ethereum) return;
  try {
    const cid = await window.ethereum.request({ method: "eth_chainId" });
    state.chainId = parseInt(cid, 16);
  } catch (e) { state.chainId = null; }
  if (state.chainId === AGENT_CARD_CONFIG.chainId) return;
  try {
    await window.ethereum.request({
      method: "wallet_switchEthereumChain",
      params: [{ chainId: "0x38" }],
    });
    state.chainId = 56;
    showToast("Jaringan dialihkan ke BNB Smart Chain.");
  } catch (err) {
    if (err && err.code === 4902) {
      try {
        await window.ethereum.request({
          method: "wallet_addEthereumChain",
          params: [{
            chainId: "0x38",
            chainName: "BNB Smart Chain",
            nativeCurrency: { name: "BNB", symbol: "BNB", decimals: 18 },
            rpcUrls: ["https://bsc-dataseed.binance.org/"],
            blockExplorerUrls: ["https://bscscan.com"],
          }],
        });
        state.chainId = 56;
      } catch (e2) {
        showToast("Add the BNB Smart Chain (56) network in your wallet.");
      }
    } else if (err && err.code === 4001) {
      showToast("Switch to BNB Smart Chain (56) to mint.");
    } else {
      showToast("Your wallet is on another network — switch to BNB Smart Chain (56).");
    }
  }
}

async function connectWallet() {
  if (!window.ethers) {
    showToast("The wallet library is not loaded yet — check your connection and try again.");
    return false;
  }
  if (!window.ethereum) { showNoWalletGuidance(); return false; }
  try {
    const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
    if (!accounts || !accounts.length) return false;
    state.connected = true;
    state.address = accounts[0];
    await ensureChain();
    await setupSigner();
    updateWalletUI();
    refreshMintUI();
    updateOwnerPanel();
    loadMyCards();
    showToast("Wallet connected: " + shortAddr(state.address));
    return true;
  } catch (e) {
    if (e && (e.code === 4001 || /rejected/i.test(String(e.message || "")))) {
      showToast("Permintaan koneksi ditolak di wallet.");
    } else {
      showToast("Failed to connect the wallet. Try again.");
    }
    return false;
  }
}

function disconnectWallet() {
  state.connected = false;
  state.address = null;
  state.chainId = null;
  signer = null;
  walletContract = null;
  updateWalletUI();
  refreshMintUI();
  updateOwnerPanel();
  const status = $("#myCardsStatus");
  if (status) status.textContent = "Connect your wallet to see your NFT cards.";
  const grid = $("#myCardsGrid");
  if (grid) grid.replaceChildren();
  showToast("Wallet disconnected on this page.");
}

function continueToConfirmation() {
  if (!validInput()) {
    $("#agentName").focus();
    showToast("Check the Agent ID name format.");
    return;
  }
  updateCard();
  updateConfirmReceipt();
  refreshMintUI();
  showView("confirmView", 2);
}

/* ---------- Real mint ---------- */

function friendlyMintError(e) {
  const raw = String((e && (e.reason || e.message || e)) || "");
  const infoMsg = e && e.info && e.info.error ? String(e.info.error.message || "") : "";
  const hay = (raw + " " + infoMsg).toLowerCase();
  if (e && (e.code === 4001 || e.code === "ACTION_REJECTED") || hay.includes("user rejected") || hay.includes("user denied")) {
    return { message: "You rejected the transaction in your wallet. No BNB moved and no card was issued.", code: "REJECTED IN WALLET" };
  }
  if (hay.includes("insufficient funds") || hay.includes("insufficient balance") || hay.includes("saldo")) {
    return { message: "Not enough BNB for the mint price plus network gas.", code: "INSUFFICIENT FUNDS" };
  }
  if (hay.includes("mint is closed")) {
    return { message: "Minting is closed by the contract owner. Try again later.", code: "MINT CLOSED" };
  }
  if (hay.includes("sold out")) {
    return { message: "The collection is sold out — every card has been minted.", code: "SOLD OUT" };
  }
  if (hay.includes("mint limit")) {
    return { message: "This wallet has reached the maximum of 2 mints per wallet.", code: "MAX MINT PER WALLET" };
  }
  if (hay.includes("name must")) {
    return { message: "The name must be 1–32 characters following the studio rules.", code: "INVALID NAME" };
  }
  if (hay.includes("insufficient bnb")) {
    return { message: "The BNB sent is less than the contract's mint price.", code: "INSUFFICIENT BNB" };
  }
  return { message: "The transaction failed. Check the details, make sure your balance and network are right, then try again.", code: (e && e.code ? String(e.code) : "TRANSACTION_ERROR").slice(0, 60) };
}

function showErrorView(message, codeText) {
  const msgEl = $("#errorMessage");
  const codeEl = $("#errorCode");
  if (msgEl) msgEl.textContent = message;
  if (codeEl) codeEl.textContent = codeText || "ERROR";
  showView("errorView", 2);
}

function setProcessStep(n) {
  ["#processStep1", "#processStep2", "#processStep3"].forEach((sel, i) => {
    const el = $(sel);
    if (el) el.classList.toggle("is-done", i < n);
  });
}

function clearProcessTimers() {
  processTimers.forEach(clearTimeout);
  processTimers = [];
}

async function runRealMint() {
  if (!validInput()) {
    $("#agentName").focus();
    showToast("Check the Agent ID name format.");
    return;
  }
  if (!state.connected) {
    const ok = await connectWallet();
    if (!ok || !state.connected) return;
  }
  if (!hasContract()) {
    showErrorView("The contract is not deployed yet — the owner will deploy it from their wallet.", "CONTRACT NOT DEPLOYED");
    return;
  }
  await ensureChain();
  if (state.chainId !== AGENT_CARD_CONFIG.chainId) {
    showErrorView("Your wallet is on another network. Switch to BNB Smart Chain (56), then try again.", "WRONG NETWORK");
    return;
  }
  if (!walletContract) await setupSigner();
  if (!walletContract || !signer) {
    showErrorView("Your wallet is not ready. Reconnect your wallet and try again.", "WALLET NOT READY");
    return;
  }
  try {
    const [freePrice, paidPrice, open, used, mcount] = await Promise.all([
      walletContract.freeMintPrice(),
      walletContract.paidMintPrice(),
      walletContract.mintOpen(),
      state.tier === 0 && state.address ? walletContract.freeMintUsed(state.address) : Promise.resolve(false),
      state.address ? walletContract.mintCount(state.address) : Promise.resolve(0),
    ]);
    state.mintCount = Number(mcount);
    chainState.freePrice = freePrice;
    chainState.paidPrice = paidPrice;
    chainState.mintOpen = Boolean(open);
    if (state.tier === 0) state.freeUsed = Boolean(used);
    updateConfirmReceipt();
    if (!chainState.mintOpen) {
      showErrorView("Minting is closed by the contract owner. Try again later.", "MINT CLOSED");
      return;
    }
    if (state.mintCount != null && state.mintCount >= 2) {
      showErrorView("This wallet already minted the maximum of 2 cards per wallet.", "MAX MINT PER WALLET");
      return;
    }
    if (state.tier === 0 && state.freeUsed) {
      showErrorView("This wallet already used its free mint (max 1x per wallet). Choose the Paid Edition to mint another card.", "FREE MINT ALREADY USED");
      return;
    }
  } catch (e) {
    showErrorView("The live mint price could not be read from the contract. Check your connection and try again.", "PRICE UNAVAILABLE");
    return;
  }

  clearProcessTimers();
  showView("processView", 2);
  setProcessStep(0);
  $("#processTitle").textContent = "Waiting for your wallet";
  $("#processMessage").textContent = "Approve the transaction in your wallet. The price of " + formatBNB(activePrice()) + " BNB + gas is shown there before you approve. BNB payments are final.";

  try {
    const mintFn = state.tier === 1 ? walletContract.paidMint : walletContract.freeMint;
    const tx = await mintFn(
      state.name,
      personaConfig[state.persona].styleIndex,
      colorConfig[state.color].hex,
      state.signature,
      { value: activePrice(), gasLimit: 600000 }
    );
    setProcessStep(1);
    $("#processTitle").textContent = "Transaction sent";
    $("#processMessage").textContent = "Hash: " + tx.hash + ". Waiting for confirmation on BNB Chain…";
    const receipt = await tx.wait();
    setProcessStep(2);
    let tokenId = null;
    try {
      const iface = new window.ethers.Interface(AGENT_CARD_ABI);
      for (const log of receipt.logs || []) {
        try {
          const parsed = iface.parseLog(log);
          if (parsed && parsed.name === "Transfer" && parsed.args[0] === window.ethers.ZeroAddress) {
            tokenId = Number(parsed.args[2]);
            break;
          }
        } catch (parseErr) { /* log lain, abaikan */ }
      }
    } catch (e) { /* fallback di bawah */ }
    if (tokenId == null) {
      try {
        const total = await readContract.totalMinted();
        tokenId = Number(total);
      } catch (e) { tokenId = (chainState.totalMinted || 0) + 1; }
    }
    mintedResult = { tokenId: tokenId, txHash: receipt.hash || tx.hash, tier: state.tier };
    if (state.signMode === "draw" && state.signDrawn) { try { localStorage.setItem("acs-sig-" + tokenId, state.signDrawn); } catch (e) { /* storage optional */ } }
    loadMintFeed(true);
    if (state.tier === 0) state.freeUsed = true;
    if (state.mintCount != null) state.mintCount += 1;
    setProcessStep(3);
    await loadChainState();
    updateCard();
    showSuccess();
    loadMyCards();
  } catch (e) {
    const friendly = friendlyMintError(e);
    const detail = e && e.message ? String(e.message).slice(0, 140) : "";
    showErrorView(friendly.message, friendly.code + (detail ? " · " + detail : ""));
  }
}

function showSuccess() {
  const tokenId = mintedResult.tokenId;
  const line = $("#successTokenLine");
  if (line) line.innerHTML = "Card <strong>No. " + pad4(tokenId) + "</strong> — " + escapeXml(state.name) + " · " + personaConfig[state.persona].title + " — now belongs to your wallet on BNB Chain.";
  const stamp = $("#successStampNo");
  if (stamp) stamp.textContent = "No. " + pad4(tokenId) + " · " + editionName(mintedResult ? mintedResult.tier : state.tier);
  const txLink = $("#txLinkButton");
  if (txLink) txLink.href = explorerTx(mintedResult.txHash);
  updateCard();
  updateXShare();
  showView("successView", 3);
  setTimeout(celebrateMint, 60);
  launchConfetti();
}

/* ---------- PNG download & sharing ---------- */

function hexMix(hex, target, f) {
  const a = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
  const b = [1, 3, 5].map((i) => parseInt(target.slice(i, i + 2), 16));
  return "#" + a.map((v, i) => Math.round(v + (b[i] - v) * f).toString(16).padStart(2, "0")).join("");
}

function serialClassLabel(id) {
  if (id <= 100) return "FOUNDER SERIAL";
  const str = String(id);
  if (id === 4444 || str === str.split("").reverse().join("") || /^(\d)\1+$/.test(str)) return "RARE SERIAL";
  return "";
}

function buildMetalSvg(opts) {
  const c = opts.colorHex;
  const L1 = hexMix(c, "#ffffff", 0.55), L2 = hexMix(c, "#ffffff", 0.22);
  const D1 = hexMix(c, "#000000", 0.38), D2 = hexMix(c, "#000000", 0.55);
  const ink = "#17130E";
  const paid = opts.tier === 1;
  const persona = personaConfig[opts.personaKey].title.toUpperCase();
  const name = escapeXml(opts.name);
  const nameSize = opts.name.length <= 10 ? 44 : opts.name.length <= 14 ? 37 : opts.name.length <= 20 ? 30 : opts.name.length <= 26 ? 25 : 21;
  const overlays = paid
    ? '<rect x="6" y="6" width="408" height="582" rx="26" fill="url(#holo)" opacity="0.16"/><rect x="6" y="6" width="408" height="582" rx="26" fill="url(#sheen)" opacity="0.5"/>'
    : '<rect x="6" y="6" width="408" height="582" rx="26" fill="url(#sheen)" opacity="0.28"/>';
  const star = (x, y, sc, op) => '<path transform="translate(' + x + ' ' + y + ') scale(' + sc + ')" d="M0 -12 L3 -3 L12 0 L3 3 L0 12 L-3 3 L-12 0 L-3 -3 Z" opacity="' + op + '"/>';
  const sparkles = '<g fill="#ffffff">'
    + star(56, 128, 1, paid ? 0.85 : 0.6) + star(356, 140, 0.7, paid ? 0.7 : 0.5) + star(84, 448, 0.6, paid ? 0.55 : 0.4)
    + star(322, 458, 0.85, paid ? 0.75 : 0.55) 
    + '</g>' + (paid ? '<g fill="#FFE9A8">' + star(210, 118, 0.55, 0.95) + star(38, 302, 0.5, 0.75) + '</g>' : '');
  const sigText = (opts.signature || "").trim();
  const frameSvg = paid ? '<use href="#fr" fill="none" stroke="#8a6a1f" stroke-opacity="0.5"/><use href="#fd" opacity="0.85"/>' : '';
  const cls = serialClassLabel(opts.serial);
  const classSvg = cls ? '<text x="210" y="364" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="700" letter-spacing="3.5" fill="#17130E" fill-opacity="0.78">&#9670; ' + cls + ' &#9670;</text>' : '';
  const sigImgSvg = opts.signatureImage ? '<image href="' + opts.signatureImage + '" x="238" y="498" width="162" height="56" preserveAspectRatio="xMaxYMax meet"/>' : '';
  const sigSvg = sigText
    ? '<text x="390" y="480" text-anchor="end" transform="rotate(-3 390 480)" font-family="\'Brush Script MT\',\'Segoe Script\',\'Snell Roundhand\',cursive" font-size="21" fill="#17130E" fill-opacity="0.85">' + escapeXml(sigText) + '</text><path d="M302 489 Q345 495 388 487" stroke="#17130E" stroke-opacity="0.35" stroke-width="1.3" fill="none" stroke-linecap="round"/>'
    : '';
  return '<svg xmlns="http://www.w3.org/2000/svg" width="840" height="1188" viewBox="0 0 420 594">'
    + '<defs>'
    + '<linearGradient id="metal" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="' + L1 + '"/><stop offset="0.2" stop-color="' + c + '"/><stop offset="0.42" stop-color="' + D1 + '"/><stop offset="0.62" stop-color="' + L2 + '"/><stop offset="0.82" stop-color="' + D2 + '"/><stop offset="1" stop-color="' + L1 + '"/></linearGradient>'
    + '<linearGradient id="sheen" x1="0" y1="0" x2="0.7" y2="1"><stop offset="0" stop-color="#ffffff" stop-opacity="0.55"/><stop offset="0.45" stop-color="#ffffff" stop-opacity="0.05"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/></linearGradient>'
    + '<linearGradient id="holo" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ff5f6d"/><stop offset="0.25" stop-color="#ffc371"/><stop offset="0.5" stop-color="#8aff80"/><stop offset="0.75" stop-color="#4dc9ff"/><stop offset="1" stop-color="#b18cff"/></linearGradient>'
    + '<linearGradient id="goldText" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8a6a1f"/><stop offset="0.5" stop-color="#f7e08b"/><stop offset="1" stop-color="#b8860b"/></linearGradient>'
    + ''
    + '<g id="geo"><circle cx="210" cy="282" r="120"/><circle cx="210" cy="282" r="76"/><line x1="86" y1="96" x2="86" y2="468"/><line x1="334" y1="96" x2="334" y2="468"/><path d="M86 152 A56 56 0 0 0 142 96"/><path d="M334 152 A56 56 0 0 1 278 96"/><path d="M86 412 A56 56 0 0 1 142 468"/><path d="M334 412 A56 56 0 0 0 278 468"/><rect x="22" y="22" width="376" height="550" rx="16"/></g><g id="fr"><rect x="30" y="30" width="360" height="534" rx="12"/><path d="M22 22 l7 -7 M398 22 l-7 -7 M22 572 l7 7 M398 572 l-7 7" stroke-linecap="round"/></g><g id="fd" fill="#8a6a1f"><rect x="-4" y="-4" width="8" height="8" transform="translate(22 22) rotate(45)"/><rect x="-4" y="-4" width="8" height="8" transform="translate(398 22) rotate(45)"/><rect x="-4" y="-4" width="8" height="8" transform="translate(22 572) rotate(45)"/><rect x="-4" y="-4" width="8" height="8" transform="translate(398 572) rotate(45)"/></g>'
    + '</defs>'
    + '<rect x="6" y="6" width="408" height="582" rx="26" fill="url(#metal)"/>'
    + overlays
    + sparkles
    + '<use href="#geo" fill="none" stroke="#17130E" stroke-opacity="0.12"/><use href="#geo" transform="translate(0 1.3)" fill="none" stroke="#ffffff" stroke-opacity="0.13"/>' + frameSvg
    + '<rect x="14" y="14" width="392" height="566" rx="20" fill="none" stroke="#ffffff" stroke-opacity="0.38" stroke-width="1.5"/>'
    + '<rect x="6" y="6" width="408" height="582" rx="26" fill="none" stroke="#000000" stroke-opacity="0.45" stroke-width="2"/>'
    + '<path d="M6 34 L158 34 L146 60 L6 60 Z" fill="#ffffff" fill-opacity="0.16" stroke="#17130E" stroke-opacity="0.18"/>'
    + '<text x="30" y="54" font-family="Arial, sans-serif" font-size="12.5" font-weight="700" letter-spacing="3.5" fill="' + ink + '" fill-opacity="0.88">AGENT CARD</text>'
    + '<text x="390" y="54" text-anchor="end" font-family="Arial, sans-serif" font-size="11.5" font-weight="700" letter-spacing="2" fill="' + ink + '" fill-opacity="0.88">ONE AND ONLY</text>'
    + '<rect x="30" y="66" width="360" height="1.4" fill="#000000" fill-opacity="0.28"/><rect x="30" y="67.6" width="360" height="1" fill="#ffffff" fill-opacity="0.35"/>'
    + '<text x="210" y="356" text-anchor="middle" font-family="Arial, sans-serif" font-size="205" font-weight="800" fill="#17130E" fill-opacity="0.055">' + escapeXml(opts.name.charAt(0)) + '</text>'
    + '<text x="211.5" y="291" text-anchor="middle" font-family="Arial, sans-serif" font-size="' + nameSize + '" font-weight="800" letter-spacing="0.5" fill="#ffffff" fill-opacity="0.35">' + name + '</text>'
    + '<text x="210" y="289.5" text-anchor="middle" font-family="Arial, sans-serif" font-size="' + nameSize + '" font-weight="800" letter-spacing="0.5" fill="' + (paid ? 'url(#goldText)' : ink) + '">' + name + '</text>'
    + '<text x="210" y="330" text-anchor="middle" font-family="Arial, sans-serif" font-size="12" font-weight="700" letter-spacing="4.5" fill="' + ink + '" fill-opacity="0.72">' + persona + '</text>'
    + classSvg
    + sigSvg
    + sigImgSvg
    + '<rect x="30" y="502" width="360" height="1.2" fill="#000000" fill-opacity="0.22"/><rect x="30" y="503.4" width="360" height="1" fill="#ffffff" fill-opacity="0.3"/>'
    + '<text x="30" y="540" font-family="Arial, sans-serif" font-size="13.5" font-weight="700" letter-spacing="1.6" fill="' + ink + '" fill-opacity="0.88">No. ' + pad4(opts.serial) + ' / ' + (chainState.maxSupply || 4444) + '</text>'
    + '<g transform="translate(291 533) rotate(45)" fill="#17130E" fill-opacity="0.8"><rect x="-4.5" y="-4.5" width="9" height="9"/></g>'
    + '<text x="390" y="540" text-anchor="end" font-family="Arial, sans-serif" font-size="12" font-weight="700" letter-spacing="2.2" fill="' + ink + '" fill-opacity="0.8">BNB CHAIN</text>'
    + '<text x="210" y="570" text-anchor="middle" font-family="Arial, sans-serif" font-size="7.5" letter-spacing="1.4" fill="' + ink + '" fill-opacity="0.55">COLLECTIBLE CARD &#183; NOT AN OFFICIAL BINANCE AGENT ID</text>'
    + "</svg>";
}

function buildCardSvg(tokenId) {
  const tier = mintedResult ? mintedResult.tier : state.tier;
  return buildMetalSvg({
    name: state.name,
    personaKey: state.persona,
    colorHex: colorConfig[state.color].hex,
    tier: tier,
    serial: tokenId,
    signature: state.signMode === "draw" ? "" : state.signature,
    signatureImage: state.signMode === "draw" ? state.signDrawn : "",
  });
}

function loadImageEl(src) {
  return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src; });
}
function drawnSignatureFor(tokenId) {
  if (mintedResult && tokenId === mintedResult.tokenId && state.signMode === "draw" && state.signDrawn) return state.signDrawn;
  try { return localStorage.getItem("acs-sig-" + tokenId) || ""; } catch (e) { return ""; }
}

async function downloadCard() {
  const tokenId = mintedResult ? mintedResult.tokenId : (chainState.totalMinted != null ? chainState.totalMinted + 1 : 1);
  let svg = null;
  let svgFromChain = false;
  if (mintedResult && readContract) {
    try {
      const meta = decodeTokenUri(await readContract.tokenURI(mintedResult.tokenId));
      if (meta && typeof meta.image === "string" && meta.image.startsWith("data:image/svg+xml;base64,")) {
        const b64img = meta.image.split(",")[1];
        svg = new TextDecoder().decode(Uint8Array.from(atob(b64img), (ch) => ch.charCodeAt(0)));
        svgFromChain = true;
      }
    } catch (e) { /* fallback ke render studio di bawah */ }
  }
  if (!svg) svg = buildCardSvg(tokenId);
  const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  try {
    const image = new Image();
    image.onload = async () => {
      const canvas = document.createElement("canvas");
      canvas.width = 840;
      canvas.height = 1188;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
      URL.revokeObjectURL(url);
      const sigData = drawnSignatureFor(tokenId);
      if (svgFromChain && sigData) {
        try {
          const sigImg = await loadImageEl(sigData);
          const sh = 96;
          const sw = sh * (sigImg.width / sigImg.height);
          ctx.drawImage(sigImg, 800 - sw, 1104 - sh, sw, sh);
        } catch (e) { /* signature overlay is optional */ }
      }
      canvas.toBlob((png) => {
        if (!png) { showToast("Failed to create the PNG. Try again."); return; }
        const downloadUrl = URL.createObjectURL(png);
        const link = document.createElement("a");
        link.href = downloadUrl;
        link.download = state.name.replace(/[^a-z0-9]+/gi, "-").toLowerCase() + "-agent-card-" + pad4(tokenId) + ".png";
        document.body.append(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(downloadUrl);
        showToast("Card PNG saved.");
      }, "image/png");
    };
    image.onerror = () => { URL.revokeObjectURL(url); showToast("Failed to create the image. Try again."); };
    image.src = url;
  } catch (error) {
    URL.revokeObjectURL(url);
    showToast("The browser cannot create an image right now.");
  }
}

function shareText() {
  if (mintedResult) {
    return "I just minted Agent Card #" + pad4(mintedResult.tokenId) + " (" + state.name + ", " + personaConfig[state.persona].title + ") on BNB Chain — the card data is stored on-chain. Not an official Binance Agent ID. Mint proof: " + explorerTx(mintedResult.txHash);
  }
  return "I designed an Agent ID card " + state.name + " (" + personaConfig[state.persona].title + ") at Agent Card Studio — a collectible NFT mint on BNB Chain, with the card data stored on-chain. Not an official Binance Agent ID.";
}

async function shareCard() {
  const payload = { title: state.name + " — Agent Card", text: shareText() };
  try {
    if (navigator.share) {
      await navigator.share(payload);
      $("#shareFeedback").textContent = "Share menu opened.";
      return;
    }
    await navigator.clipboard.writeText(payload.text);
    $("#shareFeedback").textContent = "Share text copied.";
  } catch (error) {
    if (error && error.name === "AbortError") return;
    try {
      const textArea = document.createElement("textarea");
      textArea.value = payload.text;
      document.body.append(textArea);
      textArea.select();
      document.execCommand("copy");
      textArea.remove();
      $("#shareFeedback").textContent = "Share text copied.";
    } catch (copyError) {
      $("#shareFeedback").textContent = "Sharing is not available on this device.";
    }
  }
}

/* ---------- Kartu Saya ---------- */

function decodeTokenUri(uri) {
  const prefix = "data:application/json;base64,";
  const b64 = uri.startsWith(prefix) ? uri.slice(prefix.length) : uri.split(",")[1] || "";
  const bin = atob(b64);
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function loadMyCards() {
  const status = $("#myCardsStatus");
  const grid = $("#myCardsGrid");
  if (!status || !grid) return;
  const scanId = ++myCardsScanId;
  if (hasContract() && state.connected && state.address && readContract) {
    try { state.freeUsed = Boolean(await readContract.freeMintUsed(state.address)); state.mintCount = Number(await readContract.mintCount(state.address)); refreshMintUI(); } catch (e) { /* ignore */ }
  }
  if (!hasContract()) {
    status.textContent = "The contract is not deployed yet — there are no cards to show. The owner will deploy it from their wallet.";
    grid.replaceChildren();
    return;
  }
  if (!state.address && !myCardsLookup) {
    status.textContent = "Connect your wallet — or paste an address above — to see the NFT cards.";
    grid.replaceChildren();
    return;
  }
  if (!chainState.loaded) {
    status.textContent = "Loading contract data…";
    await loadChainState();
    if (scanId !== myCardsScanId) return;
  }
  if (!readContract) {
    status.textContent = "Contract data is unavailable right now. Try reloading.";
    grid.replaceChildren();
    return;
  }
  const total = chainState.totalMinted || 0;
  if (total === 0) {
    status.textContent = "No cards have been minted yet. Be the first to mint from the studio above.";
    grid.replaceChildren();
    return;
  }
  status.textContent = "Scanning the number pool #1–" + (chainState.maxSupply || 4444).toLocaleString("en-US") + " on BNB Chain for wallet " + shortAddr(state.address) + "…";
  grid.replaceChildren();
  const owned = [];
  const scanMax = chainState.maxSupply || 4444;
  let seenMinted = 0;
  const CHUNK = 40;
  for (let start = 1; start <= scanMax; start += CHUNK) {
    if (scanId !== myCardsScanId) return;
    const ids = [];
    for (let id = start; id < Math.min(start + CHUNK, scanMax + 1); id++) ids.push(id);
    const results = await Promise.all(ids.map(async (id) => {
      try {
        const ownerAddr = await withTimeout(readContract.ownerOf(id), 8000);
        return { exists: true, id: ownerAddr.toLowerCase() === (state.address || myCardsLookup).toLowerCase() ? id : null };
      } catch (e) { return { exists: false, id: null }; }
    }));
    results.forEach((r) => { if (r && r.exists) seenMinted++; if (r && r.id != null) owned.push(r.id); });
    status.textContent = "Scanning numbers " + Math.min(start + CHUNK - 1, scanMax).toLocaleString("en-US") + "/" + scanMax.toLocaleString("en-US") + "… " + owned.length + " of yours found.";
    if (seenMinted >= total) break;
  }
  if (scanId !== myCardsScanId) return;
  if (owned.length === 0) {
    status.textContent = "Wallet " + shortAddr(state.address || myCardsLookup) + " does not own an Agent Card yet. Mint your first card from the studio above.";
    return;
  }
  status.textContent = owned.length + " cards owned by " + shortAddr(state.address || myCardsLookup) + " — images rendered from on-chain metadata.";
  for (const id of owned) {
    if (scanId !== myCardsScanId) return;
    try {
      const [cardData, uri] = await Promise.all([
        withTimeout(readContract.cards(id), 8000),
        withTimeout(readContract.tokenURI(id), 8000),
      ]);
      const meta = decodeTokenUri(uri);
      const personaKey = personaByIndex[Number(cardData[1])] || "guardian";
      const article = document.createElement("article");
      article.className = "my-card";
      const img = document.createElement("img");
      img.src = meta.image || "";
      img.alt = "Agent Card No. " + pad4(id) + " — " + cardData[0];
      const title = document.createElement("h3");
      title.textContent = cardData[0];
      const metaLine = document.createElement("p");
      metaLine.textContent = "No. " + pad4(id) + " · " + personaConfig[personaKey].title.toUpperCase() + " · " + cardData[2] + " · " + (Number(cardData[3]) === 1 ? "PAID EDITION ★" : "FREE EDITION") + (cardData[4] ? " · Signature: " + cardData[4] : "") + (String(cardData[0]).endsWith(".ai") ? " · AGENT ID .AI" : "");
      const link = document.createElement("a");
      link.href = explorerToken(id);
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      link.textContent = "View on BscScan ↗";
      const certBtn = document.createElement("button");
      certBtn.type = "button";
      certBtn.className = "outline-button my-card-cert";
      certBtn.textContent = "Download Certificate";
      certBtn.addEventListener("click", () => downloadCertificate(id, cardData, meta));
      article.append(img, title, metaLine, link, certBtn);
      grid.append(article);
    } catch (e) {
      const article = document.createElement("article");
      article.className = "my-card";
      const title = document.createElement("h3");
      title.textContent = "Agent Card No. " + pad4(id);
      const metaLine = document.createElement("p");
      metaLine.textContent = "This card's metadata cannot be read right now.";
      article.append(title, metaLine);
      grid.append(article);
    }
  }
}

/* ---------- Owner panel ---------- */

function openOwnerPanel() {
  const panel = $("#pemilik");
  if (!panel) return;
  panel.hidden = false;
  updateOwnerPanel();
  panel.scrollIntoView({ behavior: prefersReducedMotion ? "auto" : "smooth" });
}

async function updateOwnerPanel() {
  const statusEl = $("#ownerStatusText");
  const deployBlock = $("#deployBlock");
  const controls = $("#ownerControls");
  const nonOwnerNote = $("#ownerNonOwnerNote");
  if (!statusEl) return;
  if (!hasContract()) {
    statusEl.textContent = "The contract is not deployed yet. The contract address on this page is still empty — the owner deploys it from their wallet with the button below.";
    if (deployBlock) deployBlock.hidden = false;
    if (controls) controls.hidden = true;
    if (nonOwnerNote) nonOwnerNote.hidden = true;
    return;
  }
  const ownerAddr = chainState.owner;
  statusEl.innerHTML = "Contract deployed at <a href=\"" + explorerAddress(contractAddress()) + "\" target=\"_blank\" rel=\"noopener noreferrer\">" + escapeXml(contractAddress()) + "</a>"
    + (ownerAddr ? " · Owner: " + escapeXml(shortAddr(ownerAddr)) : "")
    + (chainState.paidPrice != null ? " · Free: " + escapeXml(formatBNB(chainState.freePrice)) + " BNB · Paid: " + escapeXml(formatBNB(chainState.paidPrice)) + " BNB" : "")
    + (chainState.mintOpen != null ? " · Mint: " + (chainState.mintOpen ? "open" : "closed") : "");
  if (deployBlock) deployBlock.hidden = true;
  const isOwner = state.connected && state.address && ownerAddr && state.address.toLowerCase() === ownerAddr.toLowerCase();
  if (controls) controls.hidden = !isOwner;
  if (nonOwnerNote) nonOwnerNote.hidden = Boolean(isOwner);
  if (isOwner) {
    const mintState = $("#ownerMintStateText");
    if (mintState) mintState.textContent = "Mint: " + (chainState.mintOpen ? "open" : "closed");
    const toggleBtn = $("#toggleMintButton");
    if (toggleBtn) toggleBtn.textContent = chainState.mintOpen ? "Tutup mint" : "Buka mint";
    const freeText = $("#ownerCurrentFreeText");
    if (freeText && chainState.freePrice != null) freeText.textContent = formatBNB(chainState.freePrice) + " BNB";
    const paidText = $("#ownerCurrentPaidText");
    if (paidText && chainState.paidPrice != null) paidText.textContent = formatBNB(chainState.paidPrice) + " BNB";
    refreshOwnerBalance();
  }
}

async function refreshOwnerBalance() {
  const el = $("#ownerBalanceText");
  if (!el || !hasContract() || !window.ethers) return;
  try {
    for (const rpc of READ_RPCS) {
      try {
        const provider = new window.ethers.JsonRpcProvider(rpc, AGENT_CARD_CONFIG.chainId);
        const bal = await withTimeout(provider.getBalance(contractAddress()), 8000);
        el.textContent = formatBNB(bal) + " BNB";
        return;
      } catch (e) { /* try the next RPC */ }
    }
  } catch (e) { el.textContent = "— BNB"; }
}

async function deployContract() {
  const statusEl = $("#deployStatus");
  const button = $("#deployButton");
  if (!window.ethers || !window.ethereum) {
    if (statusEl) statusEl.textContent = "No wallet detected. Open this page in a wallet app's browser.";
    return;
  }
  if (!state.connected) {
    const ok = await connectWallet();
    if (!ok) return;
  }
  await ensureChain();
  if (state.chainId !== AGENT_CARD_CONFIG.chainId) {
    if (statusEl) statusEl.textContent = "Switch your wallet network to BNB Smart Chain (56) to deploy the contract.";
    return;
  }
  if (!signer) await setupSigner();
  if (!signer) {
    if (statusEl) statusEl.textContent = "Wallet not ready. Reconnect and try again.";
    return;
  }
  if (typeof AGENT_CARD_BYTECODE !== "string" || !AGENT_CARD_BYTECODE.startsWith("0x") || AGENT_CARD_BYTECODE.length < 100) {
    if (statusEl) statusEl.textContent = "The contract bytecode is not available on this page.";
    return;
  }
  if (button) button.disabled = true;
  try {
    if (statusEl) statusEl.textContent = "Waiting for the deploy signature in your wallet…";
    const factory = new window.ethers.ContractFactory(AGENT_CARD_ABI, AGENT_CARD_BYTECODE, signer);
    const contract = await factory.deploy();
    const deployTx = contract.deploymentTransaction ? contract.deploymentTransaction() : null;
    if (statusEl) statusEl.textContent = "Contract sent" + (deployTx && deployTx.hash ? " (" + deployTx.hash + ")" : "") + ". Waiting for network confirmation…";
    await contract.waitForDeployment();
    const addr = await contract.getAddress();
    AGENT_CARD_CONFIG.contractAddress = addr;
    const result = $("#deployResult");
    const addrText = $("#deployAddressText");
    const scanLink = $("#deployBscScanLink");
    if (result) result.hidden = false;
    if (addrText) addrText.textContent = addr;
    if (scanLink) scanLink.href = explorerAddress(addr);
    if (statusEl) statusEl.textContent = "Contract deployed successfully. Its address is now active in this browser session.";
    showToast("Contract deployed: " + shortAddr(addr));
    await loadChainState();
    loadMyCards();
  } catch (e) {
    const friendly = friendlyMintError(e);
    if (statusEl) statusEl.textContent = "Deploy failed: " + friendly.message;
  } finally {
    if (button) button.disabled = false;
  }
}

async function ownerToggleMint() {
  const feedback = $("#ownerFeedback");
  if (!walletContract) await setupSigner();
  if (!walletContract) { if (feedback) feedback.textContent = "Wallet not ready."; return; }
  try {
    if (feedback) feedback.textContent = "Sending the mint-status transaction… approve it in your wallet.";
    const tx = await walletContract.setMintOpen(!chainState.mintOpen);
    await tx.wait();
    if (feedback) feedback.textContent = "Mint status updated. Hash: " + tx.hash;
    await loadChainState();
  } catch (e) {
    const friendly = friendlyMintError(e);
    if (feedback) feedback.textContent = "Failed to change the mint status: " + friendly.message;
  }
}

async function ownerSetPrice(tier) {
  const feedback = $("#ownerFeedback");
  const input = $(tier === 1 ? "#ownerPaidPriceInput" : "#ownerFreePriceInput");
  const raw = input ? input.value.trim() : "";
  const value = Number(raw);
  if (!raw || !(value >= 0) || !isFinite(value)) {
    if (feedback) feedback.textContent = "Enter a new price in BNB (0 or more).";
    return;
  }
  if (!walletContract) await setupSigner();
  if (!walletContract) { if (feedback) feedback.textContent = "Wallet not ready."; return; }
  try {
    if (feedback) feedback.textContent = "Sending the price-change transaction… approve it in your wallet.";
    const tx = tier === 1
      ? await walletContract.setPaidMintPrice(window.ethers.parseEther(raw))
      : await walletContract.setFreeMintPrice(window.ethers.parseEther(raw));
    await tx.wait();
    if (feedback) feedback.textContent = "The " + (tier === 1 ? "paid" : "free") + " mint price was changed to " + raw + " BNB. Hash: " + tx.hash;
    await loadChainState();
  } catch (e) {
    const friendly = friendlyMintError(e);
    if (feedback) feedback.textContent = "Failed to change the price: " + friendly.message;
  }
}

async function ownerWithdraw() {
  const feedback = $("#ownerFeedback");
  if (!walletContract) await setupSigner();
  if (!walletContract) { if (feedback) feedback.textContent = "Wallet not ready."; return; }
  try {
    if (feedback) feedback.textContent = "Sending the withdrawal transaction… approve it in your wallet.";
    const tx = await walletContract.withdraw();
    await tx.wait();
    if (feedback) feedback.textContent = "Contract BNB withdrawn to the owner wallet. Hash: " + tx.hash;
    refreshOwnerBalance();
  } catch (e) {
    const friendly = friendlyMintError(e);
    if (feedback) feedback.textContent = "Failed to withdraw BNB: " + friendly.message;
  }
}


/* ---------- Live mint feed ---------- */
const mintFeedCache = new Map();
let mintFeedIds = [];
let mintFeedTimer = null;
let mintFeedRetries = 0;

async function fetchMintFeedItem(id) {
  try {
    const [uri, ownerAddr, cardData] = await Promise.all([
      withTimeout(readContract.tokenURI(id), 9000),
      withTimeout(readContract.ownerOf(id), 9000),
      withTimeout(readContract.cards(id), 9000),
    ]);
    const meta = decodeTokenUri(uri);
    if (!meta || typeof meta.image !== "string") return null;
    return { id: id, img: meta.image, name: String(cardData[0] || ""), owner: ownerAddr };
  } catch (e) { return null; }
}

function renderMintFeed() {
  const track = $("#mintFeedTrack");
  const status = $("#mintFeedStatus");
  const count = $("#mintFeedCount");
  if (!track) return;
  const items = mintFeedIds.map((id) => mintFeedCache.get(id)).filter(Boolean);
  if (count && hasContract() && chainState.totalMinted != null) {
    count.innerHTML = chainState.totalMinted.toLocaleString("en-US") + " of " + (chainState.maxSupply || 4444).toLocaleString("en-US") + " cards minted so far.<br />Updates automatically.";
  }
  if (!items.length) {
    track.replaceChildren();
    track.classList.remove("is-scrolling");
    if (status) status.textContent = hasContract()
      ? "No cards have been minted yet. Be the first to mint from the studio above."
      : "The live mint feed will appear here once the contract is deployed.";
    return;
  }
  if (status) status.textContent = "Live from the contract · every card is rendered from its on-chain data · hover to pause.";
  const make = (item) => {
    const fig = document.createElement("figure");
    fig.className = "mint-feed-item";
    const img = document.createElement("img");
    img.src = item.img;
    img.alt = "Agent Card No. " + pad4(item.id) + " — " + item.name;
    img.loading = "lazy";
    const cap = document.createElement("figcaption");
    const line1 = document.createElement("strong");
    line1.textContent = "No. " + pad4(item.id) + " · " + item.name;
    const line2 = document.createElement("span");
    line2.textContent = shortAddr(item.owner);
    cap.append(line1, line2);
    fig.append(img, cap);
    return fig;
  };
  const scrolling = items.length >= 4;
  const nodes = items.map(make);
  if (scrolling) items.forEach((item) => nodes.push(make(item)));
  track.replaceChildren(...nodes);
  track.classList.toggle("is-scrolling", scrolling);
  track.style.animationDuration = Math.max(20, items.length * 7) + "s";
}

async function loadMintFeed(announce) {
  if (!hasContract()) { renderMintFeed(); return; }
  if (!readContract) {
    if (mintFeedRetries < 6) { mintFeedRetries++; setTimeout(() => loadMintFeed(announce), 4000); }
    return;
  }
  try {
    const total = Number(await withTimeout(readContract.totalMinted(), 9000));
    if (chainState.totalMinted !== total) { chainState.totalMinted = total; updateEditionLabels(); }
    const ids = (await withTimeout(readContract.recentMintIds(12), 9000)).map(Number);
    for (const id of ids) {
      if (!mintFeedCache.has(id)) {
        const item = await fetchMintFeedItem(id);
        if (item) mintFeedCache.set(id, item);
      }
    }
    const newTop = announce && mintFeedIds.length > 0 && ids.length > 0 && ids[0] !== mintFeedIds[0];
    mintFeedIds = ids;
    renderMintFeed();
    if (newTop) {
      const top = mintFeedCache.get(ids[0]);
      if (top) showToast("Baru saja termint: " + top.name + " · No. " + pad4(ids[0]));
    }
  } catch (e) { /* RPC busy — retry on the next cycle */ }
}

function startMintFeed() {
  if (mintFeedTimer) return;
  loadMintFeed(false);
  updateBurnedCount();
  mintFeedTimer = setInterval(() => { loadMintFeed(true); updateBurnedCount(); }, 30000);
}


/* ---------- Mint celebration + certificate ---------- */
function celebrateMint() {
  const view = $("#successView");
  if (!view) return;
  const card = view.querySelector(".collectible-card");
  if (!card) return;
  card.classList.remove("card-celebrate");
  void card.offsetWidth;
  card.classList.add("card-celebrate");
  const wrap = card.parentElement;
  if (!wrap) return;
  wrap.style.position = "relative";
  for (let i = 0; i < 16; i++) {
    const star = document.createElement("span");
    star.className = "burst-star";
    star.textContent = "\u2726";
    const ang = (Math.PI * 2 * i) / 16 + Math.random() * 0.4;
    const dist = 90 + Math.random() * 110;
    star.style.setProperty("--tx", Math.cos(ang) * dist + "px");
    star.style.setProperty("--ty", (Math.sin(ang) * dist - 30) + "px");
    star.style.setProperty("--rot", (Math.random() * 220 - 110) + "deg");
    star.style.animationDelay = (Math.random() * 0.15) + "s";
    wrap.append(star);
    setTimeout(() => star.remove(), 1700);
  }
}

function attachTilt(el) {
  if (!el || !window.matchMedia) return;
  if (!matchMedia("(pointer: fine)").matches) return;
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  el.addEventListener("pointermove", (ev) => {
    const r = el.getBoundingClientRect();
    const px = (ev.clientX - r.left) / r.width;
    const py = (ev.clientY - r.top) / r.height;
    el.style.transform = "perspective(900px) rotateX(" + ((0.5 - py) * 7).toFixed(2) + "deg) rotateY(" + ((px - 0.5) * 9).toFixed(2) + "deg)";
    el.style.setProperty("--mx", (px * 100).toFixed(1) + "%");
    el.style.setProperty("--my", (py * 100).toFixed(1) + "%");
  });
  el.addEventListener("pointerleave", () => { el.style.transform = ""; });
}

async function downloadCertificate(id, cardData, meta) {
  try {
    const personaKey = personaByIndex[Number(cardData[1])] || "guardian";
    const canvas = document.createElement("canvas");
    canvas.width = 1240;
    canvas.height = 880;
    const ctx = canvas.getContext("2d");
    const bgGrad = ctx.createLinearGradient(0, 0, 1240, 880);
    bgGrad.addColorStop(0, "#101319");
    bgGrad.addColorStop(1, "#1a1e28");
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, 1240, 880);
    ctx.strokeStyle = "#d4af37";
    ctx.lineWidth = 3;
    ctx.strokeRect(28, 28, 1184, 824);
    ctx.strokeStyle = "rgba(212,175,55,.45)";
    ctx.lineWidth = 1;
    ctx.strokeRect(44, 44, 1152, 792);
    ctx.textAlign = "center";
    ctx.fillStyle = "#f3d27a";
    ctx.font = "700 43px Georgia, serif";
    ctx.fillText("CERTIFICATE OF OWNERSHIP", 620, 118);
    ctx.fillStyle = "#9aa3b2";
    ctx.font = "600 19px Arial, sans-serif";
    ctx.fillText("A G E N T   C A R D   \u00B7   B N B   C H A I N", 620, 152);
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = meta.image; });
    ctx.drawImage(img, 76, 196, 309, 437);
    const savedSig = drawnSignatureFor(id);
    if (savedSig) {
      try {
        const sigImg = await loadImageEl(savedSig);
        const sh2 = 30;
        const sw2 = sh2 * (sigImg.width / sigImg.height);
        ctx.drawImage(sigImg, 370 - sw2, 604 - sh2, sw2, sh2);
      } catch (e) { /* signature overlay is optional */ }
    }
    ctx.textAlign = "left";
    let y = 250;
    ctx.fillStyle = "#ffffff";
    ctx.font = "800 44px Arial, sans-serif";
    ctx.fillText(String(cardData[0]), 440, y); y += 58;
    ctx.fillStyle = "#f3d27a";
    ctx.font = "700 27px Arial, sans-serif";
    ctx.fillText("No. " + pad4(id) + " / " + (chainState.maxSupply || 4444), 440, y); y += 46;
    ctx.fillStyle = "#c9ccd4";
    ctx.font = "20px Arial, sans-serif";
    ctx.fillText("Persona: " + personaConfig[personaKey].title, 440, y); y += 32;
    ctx.fillText("Edition: " + (Number(cardData[3]) === 1 ? "Paid" : "Free"), 440, y); y += 32;
    const clsLabel = serialClassLabel(id);
    if (clsLabel) { ctx.fillText("Serial Class: " + clsLabel, 440, y); y += 32; }
    if (cardData[4]) { ctx.fillText("Signature: " + cardData[4], 440, y); y += 32; }
    y += 14;
    ctx.fillStyle = "#9aa3b2";
    ctx.font = "600 15px Arial, sans-serif";
    ctx.fillText("OWNER", 440, y); y += 24;
    ctx.fillStyle = "#e8eaf0";
    ctx.font = "16px ui-monospace, monospace";
    ctx.fillText(state.address || "", 440, y); y += 44;
    ctx.fillStyle = "#9aa3b2";
    ctx.font = "600 15px Arial, sans-serif";
    ctx.fillText("CONTRACT", 440, y); y += 24;
    ctx.fillStyle = "#e8eaf0";
    ctx.font = "16px ui-monospace, monospace";
    ctx.fillText(contractAddress(), 440, y); y += 44;
    ctx.fillStyle = "#9aa3b2";
    ctx.font = "15px Arial, sans-serif";
    ctx.fillText("Printed " + new Date().toLocaleDateString("en-US", { day: "numeric", month: "long", year: "numeric" }), 440, y);
    ctx.textAlign = "center";
    ctx.fillStyle = "#77808f";
    ctx.font = "14px Arial, sans-serif";
    ctx.fillText("This certificate is generated from on-chain data. Agent Card is a collectible card, not an official Binance Agent ID.", 620, 800);
    canvas.toBlob((png) => {
      if (!png) { showToast("Failed to create the certificate. Try again."); return; }
      const url = URL.createObjectURL(png);
      const link = document.createElement("a");
      link.href = url;
      link.download = "certificate-" + String(cardData[0]).replace(/[^a-z0-9]+/gi, "-").toLowerCase() + "-" + pad4(id) + ".png";
      document.body.append(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
      showToast("Certificate saved.");
    }, "image/png");
  } catch (e) {
    showToast("Failed to create the certificate. Try again.");
  }
}

