const checkBtn = $("#checkMintsButton");
if (checkBtn) checkBtn.addEventListener("click", async () => {
  const out = $("#checkResult");
  const addr = ($("#checkAddress").value || "").trim();
  if (!window.ethers || !window.ethers.isAddress(addr)) { if (out) out.textContent = "Enter a valid 0x wallet address."; return; }
  if (!hasContract() || !readContract) { if (out) out.textContent = "The contract is not deployed yet - mint has not opened."; return; }
  if (out) out.textContent = "Reading the chain...";
  try {
    const [used, count] = await Promise.all([readContract.freeMintUsed(addr), readContract.mintCount(addr)]);
    const left = Math.max(0, 2 - Number(count));
    if (out) out.textContent = "Free mint: " + (used ? "already used" : "still available (0.0002 BNB fee)") + " - Cards minted: " + Number(count) + " of 2 - You can still mint " + left + " card(s).";
  } catch (e) { if (out) out.textContent = "Could not read the chain right now - try again in a moment."; }
});
