async function fundPool(which) {
  const addr = which === "burn" ? burnAddress() : stakeAddress();
  const input = $(which === "burn" ? "#fundBurnInput" : "#fundStakeInput");
  if (!tokenAddress()) { showToast("Deploy $ACARD first."); return; }
  if (!addr) { showToast("Deploy the " + which + " contract first."); return; }
  const signer = await ownerSigner();
  if (!signer) return;
  try {
    const token = new window.ethers.Contract(tokenAddress(), TOKEN_ABI, signer);
    const tx = await token.transfer(addr, window.ethers.parseEther(String((input && input.value) || "0")));
    await tx.wait();
    showToast("Pool funded: " + (input ? input.value : "") + " $ACARD to the " + which + " contract.");
  } catch (e) { showToast(friendlyError(e)); }
}
const fundBurnBtn = $("#fundBurnButton");
if (fundBurnBtn) fundBurnBtn.addEventListener("click", () => fundPool("burn"));
const fundStakeBtn = $("#fundStakeButton");
if (fundStakeBtn) fundStakeBtn.addEventListener("click", () => fundPool("stake"));
const linkNftBtn = $("#linkNftButton");
if (linkNftBtn) linkNftBtn.addEventListener("click", async () => {
  if (!hasContract()) { showToast("Deploy the NFT contract first."); return; }
  const signer = await ownerSigner();
  if (!signer) return;
  linkNftBtn.disabled = true;
  try {
    if (burnAddress()) { const b = new window.ethers.Contract(burnAddress(), REWARD_ABI, signer); await (await b.setNft(contractAddress())).wait(); }
    if (stakeAddress()) { const st = new window.ethers.Contract(stakeAddress(), REWARD_ABI, signer); await (await st.setNft(contractAddress())).wait(); }
    showToast("Burn & Stake now point at the NFT contract.");
  } catch (e) { showToast(friendlyError(e)); }
  linkNftBtn.disabled = false;
});

